"""Second pass: look up abstract-only rows that still have no PDF by exact-ish title on the arXiv API."""
import csv, os, re, urllib.request, urllib.parse, time, difflib
import xml.etree.ElementTree as ET
UA={'User-Agent':'litdb-fetch/1.0'}
def get(u): return urllib.request.urlopen(urllib.request.Request(u,headers=UA),timeout=40).read()
def norm(s): return re.sub(r'[^a-z0-9 ]','',s.lower())
ns={'a':'http://www.w3.org/2005/Atom'}
for r in csv.DictReader(open('docs/literature/literature_matrix.csv',encoding='utf-8')):
    k=r['key']
    if r['read_depth']!='ABS' or os.path.exists(f'litdb/incoming/{k}.pdf'): continue
    t=r['title'].split(':')[0] if len(r['title'])>90 else r['title']
    q=urllib.parse.quote('ti:"'+re.sub(r'[^A-Za-z0-9 ]',' ',t)+'"')
    try:
        root=ET.fromstring(get(f'http://export.arxiv.org/api/query?search_query={q}&max_results=3'))
    except Exception as e:
        print(k,'ERR',str(e)[:40]); continue
    best=None
    for e in root.findall('a:entry',ns):
        et=e.find('a:title',ns).text
        sc=difflib.SequenceMatcher(None,norm(et),norm(r['title'])).ratio()
        if best is None or sc>best[0]: best=(sc,et,e.find('a:id',ns).text)
    if best and best[0]>0.85:
        pid=best[2].split('/abs/')[1]
        try:
            b=get(f'https://arxiv.org/pdf/{pid}')
            if b[:5]==b'%PDF-':
                open(f'litdb/incoming/{k}.pdf','wb').write(b); print(k,'OK',pid,round(best[0],2)); 
        except Exception as e: print(k,'dlfail',str(e)[:40])
    else: print(k,'none',round(best[0],2) if best else '-')
    time.sleep(3)
PYEOF
python litdb/tools/fetch_arxiv_title.py 2>&1 | grep -E " OK |ERR|dlfail"; ls litdb/incoming | wc -l

