cd "C:/Users/MITE/AppData/Local/Temp/claude/C--Users-MITE-Downloads-final-project--short-and-sweet-/30722764-8396-4e50-b80a-fc775d4bc516/scratchpad/newrepo" && cat > ../short.py <<'PYEOF'
import os,re
base='literature-review'
rows=[l.split('|') for l in open(os.path.join(base,'KEY_MAP.md'),encoding='utf-8') if l.startswith('| ') and not l.startswith('| Repo')]
m={r[2].strip():r[1].strip() for r in rows}
pat=re.compile(r'\b([a-z]{3,})\.\.\.(\d{4}[a-z]+)\b')
n=0
for root,_,files in os.walk(base):
    for f in files:
        if not f.endswith('.md'): continue
        p=os.path.join(root,f); t=open(p,encoding='utf-8').read()
        def rep(mo):
            global n
            for k,v in m.items():
                if k.startswith(mo.group(1)) and k.endswith(mo.group(2)): n+=1; return v
            return mo.group(0)
        t2=pat.sub(rep,t)
        if t2!=t: open(p,'w',encoding='utf-8').write(t2)
print(n)
PYEOF
python ../short.py; grep -rhoE "\b[a-z]{3,}\.\.\.[0-9]{4}[a-z]+" literature-review | sort -u | head

